'use strict';
const content=document.getElementById('content'),platform=document.getElementById('platform'),surface=document.getElementById('play-surface'),frame=document.getElementById('game-frame');
const frames={minesweeper:frame,rocket:document.getElementById('rocket-frame'),dice:document.getElementById('dice-frame'),plinko:document.getElementById('plinko-frame'),horse:document.getElementById('horse-frame')};
const session={visited:false,loaded:false,activeGame:'minesweeper',loadedGames:new Set(),points:1000,rounds:[],ledger:[{label:'首次体验赠送',amount:1000,time:'本次会话'}],claims:new Set(),finished:new Set()};let page='games',filter='全部';
const catalog=[
{id:'minesweeper',name:'金币扫雷',category:'概率',description:'逐格翻开奖励，踩雷前主动收取',cost:'50 积分 / 局',cover:'sweep-cover',available:true},
{id:'rocket',name:'小火箭',category:'反应',description:'飞得越久奖励越高，坠毁前收取',cost:'50 积分 / 局',cover:'cover-rocket',available:true},
{id:'dice',name:'三骰挑战',category:'概率',description:'选定模式，掷出你的幸运组合',cost:'50 积分 / 局',cover:'cover-dice',available:true},
{id:'plinko',name:'闪电跑道',category:'概率',description:'选择落球入口，落袋揭晓奖励',cost:'50 积分 / 局',cover:'cover-plinko',available:true},
{id:'horse',name:'星际赛马',category:'概率',description:'选择你的赛马，冲线揭晓名次奖励',cost:'50 积分 / 局',cover:'cover-horse',available:true},
{id:'2048',name:'2048',category:'益智'},
{id:'memory',name:'记忆翻牌',category:'益智'},
{id:'rhythm',name:'节奏点击',category:'反应'}];
function renderLobby(){
 const games=catalog.filter(g=>g.available&&(filter==='全部'||g.category===filter));
 const upcoming=catalog.filter(g=>!g.available&&(filter==='全部'||g.category===filter));
 return `<div class="welcome"><h1>今天，玩点什么？</h1><span class="lobby-count">${catalog.filter(g=>g.available).length} 款可玩</span></div>
 ${session.visited?`<div class="continue"><div><h2>${gameName(session.activeGame)}</h2><p class="muted">最近玩过</p></div><button class="primary" data-play="${session.activeGame}">回到游戏</button></div>`:''}
 <div class="section-row"><h2 class="sr-only">探索游戏</h2><div class="filters" aria-label="游戏分类">${['全部','益智','反应','概率'].map(c=>`<button class="filter" data-filter="${c}" aria-pressed="${filter===c}">${c}</button>`).join('')}</div></div>
 <div class="catalog">${games.map(g=>`<button class="game-card" data-play="${g.id}" aria-label="${g.name}，${g.cost}，进入游戏"><div class="cover ${g.cover}"><span class="card-category">${g.category}</span><span class="icon-motion" aria-hidden="true"><i class="icon-spark"></i><span class="lobby-art art-${g.id}"></span><i class="icon-spark"></i></span></div><div class="game-details"><h2>${g.name}</h2><p class="game-description">${g.description}</p><div class="card-bottom"><span class="entry-cost">${g.cost}</span><span class="play-label">进入游戏 <span aria-hidden="true">›</span></span></div></div></button>`).join('')}</div>
 ${upcoming.length?`<section class="upcoming" aria-label="即将上线"><h2>即将上线</h2><div class="upcoming-list">${upcoming.map(g=>`<span>${g.name}</span>`).join('')}</div></section>`:''}
 <p class="catalog-footer">模拟积分仅供体验，刷新后重置。</p>`;
}

function showPage(next){page=['games','rewards','me'].includes(next)?next:'games';platform.hidden=false;surface.hidden=true;if(session.loadedGames.has('rocket'))frames.rocket.contentWindow.postMessage({type:'platform-pause',paused:true},location.origin);if(session.loadedGames.has('dice'))frames.dice.contentWindow.postMessage({type:'platform-pause',paused:true},location.origin);if(session.loadedGames.has('horse'))frames.horse.contentWindow.postMessage({type:'platform-pause',paused:true},location.origin);if(session.loadedGames.has('minesweeper'))frame.contentWindow.postMessage({type:'platform-pause',paused:true},location.origin);document.querySelectorAll('.navigation button').forEach(b=>{if(b.dataset.page===page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});render();window.scrollTo(0,0)}
function render(){document.getElementById('header-points').textContent=session.points.toLocaleString();if(page==='games'){content.innerHTML=renderLobby()}else if(page==='rewards'){content.innerHTML=`<h1>我的奖励</h1><p class="muted">游戏积分与链上资产，分别查看。</p><div class="panel-grid"><section class="panel"><h2>本次体验积分</h2><div class="balance">${formatPoints(session.points)}<span>积分</span></div><p class="muted">首次赠送 1,000 积分；各游戏每局消耗 50 积分，奖励含本局投入。</p></section><section class="panel"><h2>链上资产</h2><div class="empty">尚未接入钱包</div><p class="muted">当前版本没有充值、提现或真实交易。</p></section></div><section class="panel list-panel"><h2>积分明细</h2>${session.ledger.slice().reverse().map(r=>`<div class="record"><div>${r.label}<small>${r.time}</small></div><span class="${r.amount>0?'positive':'muted'}">${r.amount>0?'+':''}${formatPoints(r.amount)} 积分</span></div>`).join('')}</section><p class="notice">积分仅用于本次 Demo 体验，刷新后重置为初始赠送积分，不具有货币价值。</p>`}else{content.innerHTML=`<h1>我的</h1><div class="profile"><span class="avatar">P</span><div><h2>游客玩家</h2><p class="muted">先玩一局，轻松探索</p></div></div><div class="panel-grid"><section class="panel"><h2>本次游戏记录</h2>${session.rounds.length?session.rounds.slice().reverse().map(r=>`<div class="record"><div>${gameName(r.gameId)}<small>${r.time} · ${r.seconds} 秒</small></div><span class="${r.won?'positive':'muted'}">${r.gameId==='horse'?('第 '+r.rank+' 名 · '+r.amount+' 积分'):r.gameId==='plinko'?('落袋 '+r.multiplier+'× · '+r.amount+' 积分'):r.gameId==='dice'?(r.won?'命中 · '+r.amount+' 积分':'未命中 · 0 积分'):r.gameId==='rocket'?(r.won?'已收取 '+r.amount+' 积分':'已坠毁 · 0 积分'):(r.won?'已收取 '+formatPoints(r.amount)+' 积分':r.state==='forfeited'?'已结束 · 0 积分':'踩到地雷 · 0 积分')}</span></div>`).join(''):'<div class="empty">还没有完成的游戏。</div><button class="primary" data-play>开始第一局</button>'}</section><section><div class="rows"><button class="row-button" data-help="account"><span>账户与钱包</span><span>未接入 ›</span></button><button class="row-button" data-help="rules"><span>玩法说明</span><span>游戏规则 ›</span></button><button class="row-button" data-help="about"><span>关于 PLAYROOM</span><span>Demo ›</span></button></div><p class="notice">游戏记录仅保留在本次页面会话中。</p></section></div>`}}
function gameName(id){return {horse:'星际赛马',plinko:'闪电跑道',rocket:'小火箭',dice:'三骰挑战',minesweeper:'金币扫雷'}[id]||'游戏'}
function timeLabel(){return new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}
function addLedger(label,amount){session.ledger.push({label,amount,time:timeLabel()})}
function formatPoints(n){return n.toLocaleString('zh-CN',{maximumFractionDigits:2})}
function chargePoints(cost,label){const cents=Math.round(session.points*100),debit=Math.round(cost*100);if(cents<debit)return false;session.points=(cents-debit)/100;addLedger(label,-cost);return true}
function creditPoints(amount,label){session.points=(Math.round(session.points*100)+Math.round(amount*100))/100;addLedger(label,amount)}
const rocketRound=new RocketRound({charge(cost){return chargePoints(cost,'小火箭 · 发射消耗')},credit(amount){creditPoints(amount,'小火箭 · 主动收取')},onFinish(r){session.rounds.push({...r,time:timeLabel()});if(!r.won)addLedger('小火箭 · 坠毁，奖励归零',0);if(!platform.hidden)render()}});
function syncRocket(){if(session.loadedGames.has('rocket')){rocketRound.tick();frames.rocket.contentWindow.postMessage(rocketRound.snapshot(session.points),location.origin)}}
const diceRound=new DiceRound({charge(cost){return chargePoints(cost,'三骰挑战 · 掷骰消耗')},credit(amount){creditPoints(amount,'三骰挑战 · 命中奖励')},onFinish(r){session.rounds.push({...r,time:timeLabel()});if(!r.won)addLedger('三骰挑战 · 未命中',0);if(!platform.hidden)render()}});
function syncDice(){if(session.loadedGames.has('dice')){diceRound.tick();frames.dice.contentWindow.postMessage(diceRound.snapshot(session.points),location.origin)}}
const plinkoRound=new PlinkoRound({charge(cost){return chargePoints(cost,'闪电跑道 · 落球消耗')},credit(amount){creditPoints(amount,'闪电跑道 · 落袋奖励')},onFinish(r){session.rounds.push({...r,time:timeLabel()});if(!platform.hidden)render()}});
function syncPlinko(full=false){if(session.loadedGames.has('plinko')){plinkoRound.tick();frames.plinko.contentWindow.postMessage(plinkoRound.snapshot(session.points,full),location.origin)}}
const minesRound=new MinesRound({charge(cost){return chargePoints(cost,'金币扫雷 · 开局消耗')},credit(amount){creditPoints(amount,'金币扫雷 · 主动收取')},onFinish(r){session.rounds.push({...r,time:timeLabel()});if(!r.won)addLedger(r.state==='forfeited'?'金币扫雷 · 结束本局':'金币扫雷 · 踩雷，奖励归零',0);if(!platform.hidden)render()}});
function syncMines(){if(session.loadedGames.has('minesweeper'))frame.contentWindow.postMessage(minesRound.snapshot(session.points),location.origin)}
const horseRound=new HorseRound({charge(cost){return chargePoints(cost,'星际赛马 · 参赛消耗')},credit(amount){creditPoints(amount,'星际赛马 · 名次奖励')},onFinish(r){session.rounds.push({...r,time:timeLabel()});if(!r.amount)addLedger('星际赛马 · 第 4 名，奖励 0',0);if(!platform.hidden)render()}});
function syncHorse(){if(session.loadedGames.has('horse')){horseRound.tick();frames.horse.contentWindow.postMessage(horseRound.snapshot(session.points),location.origin)}}
function play(id='minesweeper'){if(!frames[id])return;session.visited=true;session.activeGame=id;platform.hidden=true;surface.hidden=false;for(const [key,f] of Object.entries(frames)){f.hidden=key!==id;if(['minesweeper','horse','dice','rocket'].includes(key)&&session.loadedGames.has(key))f.contentWindow.postMessage({type:'platform-pause',paused:key!==id},location.origin)}if(!session.loadedGames.has(id)){frames[id].src={horse:'horse.html?v=park60',plinko:'plinko.html?v=expedition59b',rocket:'rocket.html?v=scale63',dice:'dice.html?v=aurora57',minesweeper:'minesweeper.html?v=treasure58'}[id];session.loadedGames.add(id);session.loaded=true}else if(id==='rocket')syncRocket();else if(id==='dice')syncDice();else if(id==='plinko')syncPlinko(true);else if(id==='minesweeper')syncMines();else if(id==='horse')syncHorse();window.scrollTo(0,0)}

function help(kind){const copy={account:['账户与钱包','当前使用游客模式，无需注册即可试玩。\n账户绑定和钱包连接尚未接入。'],rules:['游戏怎么玩？','金币扫雷：54 格中固定藏着 10 颗雷，每局开始时随机生成。\n每次只翻开一格，没有数字提示或首次保护。金币颜色不提供线索。\n每局消耗 50 积分，成功揭开至少一格后可随时收取。奖励含本局投入；踩雷时本局奖励归零，开局消耗不退还。\n奖励按理论返还率 97% 计算，保留两位小数并向下取整，实际返还率略低。揭开全部安全格自动收取，返回大厅可保留当前局。\n\n小火箭：每局消耗 50 积分。飞行越久倍率越高，可随时主动收取；坠毁前未收取则本局奖励归零。收取得分含本局投入，切出页面不会暂停。\n\n三骰挑战：每局消耗 50 积分。可选大小、指定总点数、任意三同号；大小排除三同号。命中后自动发放界面所示奖励（含投入），未命中无奖励。\n\n闪电跑道：每局 50 积分，选择入口释放弹珠，按落袋倍率自动发放积分（含投入）；低于 1 倍会损失部分投入。返回大厅不暂停结算。\n\n星际赛马：每局 50 模拟积分，四匹马选一匹。每匹马任一名次的概率均为 25%，第 1–4 名到账 140、40、14、0 积分（含投入），理论返还率 97%。开赛时随机决定名次，再播放竞速动画。返回大厅后继续自动结算。'],about:['关于 PLAYROOM','一个轻量休闲游戏平台 Demo。\n当前可玩：金币扫雷、小火箭、三骰挑战、闪电跑道、星际赛马。其他游戏正在筹备中。\n所有奖励均为模拟积分，不涉及真实资产。']};document.getElementById('help-title').textContent=copy[kind][0];document.getElementById('help-text').textContent=copy[kind][1];document.getElementById('help').showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-play'))play(b.dataset.play||'minesweeper');else if(b.dataset.page){location.hash=b.dataset.page;showPage(b.dataset.page)}else if(b.dataset.filter){filter=b.dataset.filter;render()}else if(b.dataset.help)help(b.dataset.help)});
for(const id of ['help-close','help-ok'])document.getElementById(id).onclick=()=>document.getElementById('help').close();window.addEventListener('hashchange',()=>showPage(location.hash.slice(1)));
window.addEventListener('message',e=>{if(e.origin!==location.origin||!e.data||typeof e.data!=='object')return;const gameId=Object.keys(frames).find(id=>frames[id].contentWindow===e.source);if(!gameId||!session.loadedGames.has(gameId))return;const d=e.data;if(d.type==='game-return'){showPage('games');return}if(gameId==='horse'){if(d.type==='horse-start'&&!horseRound.start(d.selected,d.roundId))frames.horse.contentWindow.postMessage({type:'horse-error',message:session.points<50?'积分不足，参赛需要 50 积分。':'本局正在进行，请等待比赛结束。'},location.origin);if(['horse-ready','horse-start'].includes(d.type))syncHorse();return}if(gameId==='plinko'){if(d.type==='plinko-drop'&&!plinkoRound.start(d.lane))frames.plinko.contentWindow.postMessage({type:'plinko-error',message:'暂时无法落球，请检查积分或等待本局结束。'},location.origin);if(['plinko-ready','plinko-drop'].includes(d.type))syncPlinko(true);return}if(gameId==='dice'){if(d.type==='dice-roll'&&!diceRound.start(d.mode,d.target))frames.dice.contentWindow.postMessage({type:'dice-error',message:'暂时无法掷骰，请检查积分和模式。'},location.origin);if(['dice-ready','dice-roll'].includes(d.type))syncDice();return}if(gameId==='rocket'){if(d.type==='rocket-launch'){if(!rocketRound.start())frames.rocket.contentWindow.postMessage({type:'rocket-error',message:rocketRound.state==='flying'?'已有火箭在飞行。':'积分不足，本局需要 50 积分。'},location.origin)}else if(d.type==='rocket-collect')rocketRound.collect();if(['rocket-ready','rocket-launch','rocket-collect'].includes(d.type))syncRocket();return}
if(d.type==='mines-ready'){syncMines();return}
let ok;switch(d.type){case 'mines-start':ok=minesRound.start(d.roundId);break;case 'mines-reveal':ok=minesRound.reveal(d.index,d.roundId);break;case 'mines-flag':ok=minesRound.flag(d.index,d.roundId);break;case 'mines-collect':ok=minesRound.collect(d.roundId);break;case 'mines-forfeit':ok=minesRound.forfeit(d.roundId);break;default:return}
if(!ok)frame.contentWindow.postMessage({type:'mines-error',message:d.type==='mines-start'&&session.points<50?'积分不足，开局需要 50 积分。':'本次操作未生效，请查看当前棋盘。'},location.origin);syncMines();if(!platform.hidden)render()});
setInterval(()=>{if(!surface.hidden&&session.activeGame==='minesweeper')syncMines()},1000);
setInterval(()=>{syncRocket();syncDice();syncPlinko();syncHorse()},100);

showPage(location.hash.slice(1));
